  Notation HEAD4 pc mm q pt bits c a1 a3 a4 x9 x18 x19 x20 x21 xra :=
    (MS (mkR xra (Z_to_bv 64 SPF) gp tp (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap)) c (Z_to_bv 64 64) x9
             (Z_to_bv 64 (DST + q)) a1 (Z_to_bv 64 SS) a3 a4 (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 2147450880)
             x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 pt) (Z_to_bv 64 bits) (Z_to_bv 64 (DST + dcap - 7)) (Z_to_bv 64 8))
        FR (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

