  Lemma ax2_l4dec : forall q pt mm (c a1 a3 a4 t4 x9 x18 x19 x20 x21 xra : word),
    (forall q' pt' bits' mm' (c' a1' a3' a4' x9' x18' x19' x20' x21' xra' : word),
       AX2M' mm' -> q < q' <= dcap -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= n) -> 0 <= bits' <= 64 ->
       evtF asegs RNG POST (HEAD4 0x844ec mm' q' pt' bits' c' a1' a3' a4' x9' x18' x19' x20' x21' xra')) ->
    0 <= q -> q + 8 <= dcap -> 0 <= pt -> (pt = 0 \/ pt + 8 <= n) -> AX2M' mm ->
    evtF asegs RNG POST (MS (mkR xra (Z_to_bv 64 SPF) gp tp (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap)) c
             (Z_to_bv 64 64) x9 (Z_to_bv 64 (DST + q)) a1 (Z_to_bv 64 SS) a3 a4 (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 (DT + 4))
             (Z_to_bv 64 2147450880) x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 pt) t4 (Z_to_bv 64 (DST + dcap - 7))
             (Z_to_bv 64 8))
        FR (Z_to_bv 64 0x845c0) fc None mm (seg_rom asegs)).
