  Ltac ax2_rl2_facts mm MU :=
    pose proof (A2 ax2_unp mm MU) as (UDT' & UDB' & USB');
    pose proof (A2 ax2_blocks) as (B1 & B2 & B3 & B4 & B5 & B6); destruct (B6 ltac:(lia)) as (Q1 & Q2 & Q3 & Q4');
    pose proof (A2 ax2_sp_bounds) as SB;
    assert (LSM : Z.of_nat (length (map (Z_to_bv 8) src)) = n) by (rewrite length_map; reflexivity);
    pose proof (bv_unsigned_in_range 64 sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
    pose proof ATOP_range as ATR; unfold ATOP_MIN, ATOP_MAX in ATR;
    unfold AIMG_HI, KLS in *; unfold ablk, AIMG_HI, KLS in SBA.

  (* [comment removed for export] *)
  Ltac ax2_l4rl_run q pt nb cs :=
    lazymatch cs with
    | 0 =>
      kx_runFL [0x845ec] 80%nat
        [KZRange nb 0 8; KZRange pt 0 (2^26); KZRange n 1 (2^26); KZRange (pt - nb) 0 (2^26); KZRange (n - (pt - nb)) 8 (2^26);
         KZRange SS 16 (2^47 - 8388608); KZRange DST 0x5ed000 (2^47 - 8388608); KZRange q 0 (2^32); KZRange dcap 8 (2^32)]
        [(SS + (pt - nb), 8)] [(SS + (pt - nb), 8)] [(SS + (pt - nb), 8)]
    | 1 =>
      kx_runFL [0x845ec] 80%nat
        [KZRange (q + 7 - dcap) 0 (2^32);
         KZRange nb 0 8; KZRange pt 0 (2^26); KZRange n 1 (2^26); KZRange (pt - nb) 0 (2^26); KZRange (n - (pt - nb)) 8 (2^26);
         KZRange SS 16 (2^47 - 8388608); KZRange DST 0x5ed000 (2^47 - 8388608); KZRange q 0 (2^32); KZRange dcap 8 (2^32)]
        [(SS + (pt - nb), 8)] [(SS + (pt - nb), 8)] [(SS + (pt - nb), 8)]
    | 2 =>
      kx_runFL [0x845ec] 80%nat
        [KZRange (dcap - 8 - q) 0 (2^32);
         KZRange nb 0 8; KZRange pt 0 (2^26); KZRange n 1 (2^26); KZRange (pt - nb) 0 (2^26); KZRange (n - (pt - nb)) 8 (2^26);
         KZRange SS 16 (2^47 - 8388608); KZRange DST 0x5ed000 (2^47 - 8388608); KZRange q 0 (2^32); KZRange dcap 8 (2^32)]
        [(SS + (pt - nb), 8)] [(SS + (pt - nb), 8)] [(SS + (pt - nb), 8)]
    end;
    try (lazymatch goal with |- evtF _ _ _ _ => fail | _ => unfold KXGoM.apart in *; lia end).

  (* [comment removed for export] *)
  Lemma ax2_l4rl : forall q pt nb stt mm (a1 t4 x18 x19 x20 x21 xra x9 x13 : word),
    (forall q' pt' bits' mm' (c' a1' a3' a4' x9' x18' x19' x20' x21' xra' : word),
       AX2M' mm' -> q < q' <= dcap -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= n) -> 0 <= bits' <= 64 ->
       evtF asegs RNG POST (HEAD4 0x844ec mm' q' pt' bits' c' a1' a3' a4' x9' x18' x19' x20' x21' xra')) ->
    0 <= q <= dcap -> 8 <= dcap -> 0 <= nb <= 8 -> nb <= pt -> pt - nb + 8 <= n -> (stt = 0 \/ stt = 1) -> AX2M' mm ->
    evtF asegs RNG POST (MS (mkR xra (Z_to_bv 64 SPF) gp tp (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 stt)
             (Z_to_bv 64 64) x9 (Z_to_bv 64 (DST + q)) a1 (Z_to_bv 64 SS) x13 (Z_to_bv 64 nb) (Z_to_bv 64 (64 - tl))
             (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 2147450880) x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 pt) t4
             (Z_to_bv 64 (DST + dcap - 7)) (Z_to_bv 64 8))
        FR (Z_to_bv 64 0x84528) fc None mm (seg_rom asegs)).
