  Lemma ax2_l4head : forall q pt bits mm (c a1 a3 a4 x9 x18 x19 x20 x21 xra : word),
    (forall q' pt' bits' mm' (c' a1' a3' a4' x9' x18' x19' x20' x21' xra' : word),
       AX2M' mm' -> q < q' <= dcap -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= n) -> 0 <= bits' <= 64 ->
       evtF asegs RNG POST (HEAD4 0x844ec mm' q' pt' bits' c' a1' a3' a4' x9' x18' x19' x20' x21' xra')) ->
    0 <= q <= dcap -> 8 <= dcap -> 0 <= pt -> (pt = 0 \/ pt + 8 <= n) -> 0 <= bits <= 64 -> AX2M' mm ->
